package huihuang.proxy.ocpx.util;

import cn.hutool.core.net.URLEncoder;

import java.nio.charset.StandardCharsets;

public class EncodeUtil {

    public static void main(String[] args) {
        String str = "http://ocpc.baidu.com/ocpcapi/cb/actionCb?a_type={{ATYPE}}%26a_value={{AVALUE}}%26s=8733784531242421502%26o=1733802895467%26actType=2%26ext_";
        System.out.println(encode(str));
    }

    public static String encode(String str) {
        return URLEncoder.createQuery().encode(str, StandardCharsets.UTF_8);
    }

}
